import unittest
from candidate import median

class TestMedianFunction(unittest.TestCase):
    def test_median_of_positive_numbers(self):
        self.assertEqual(median([3, 1, 2, 4, 5]), 3)

    def test_median_of_mixed_numbers(self):
        self.assertEqual(median([-10, 4, 6, 1000, 10, 20]), 15.0)

    def test_median_of_single_element_list(self):
        self.assertEqual(median([5]), 5)

    def test_median_of_two_element_list(self):
        self.assertEqual(median([3, 4]), 3.5)

    def test_median_of_empty_list(self):
        with self.assertRaises(IndexError):
            median([])

    def test_median_of_list_with_none(self):
        with self.assertRaises(TypeError):
            median([1, 2, None, 4, 5])

    def test_median_of_list_with_non_numeric(self):
        with self.assertRaises(TypeError):
            median([1, 2, 'a', 4, 5])

    def test_median_of_list_with_floats(self):
        self.assertEqual(median([1.5, 2.5, 3.5, 4.5]), 3.5)

    def test_median_of_list_with_negative_and_floats(self):
        self.assertEqual(median([-1.5, 2.5, 3.5, 4.5]), 3.0)

if __name__ == '__main__':
    unittest.main()
